/// Authored circuits: 40.
pub const AUTHORED_TRACK_COUNT: usize = 40;
pub const TOTAL_TRACKS: usize = 40;

/// Game mode classification.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum GameMode {
    GrandPrix = 0,
    Mania = 1,
    FreeRoam = 2,
}

/// Cup specification grouping a sequence of circuit indices.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub struct CupDef {
    pub name: &'static str,
    pub mode: GameMode,
    pub track_indices: &'static [usize],
}

impl CupDef {
    pub const fn track_at(&self, stage: usize) -> Option<&'static TrackDef> {
        if stage < self.track_indices.len() {
            Some(ALL_TRACKS[self.track_indices[stage]])
        } else {
            None
        }
    }
    pub const fn total_stages(&self) -> usize {
        self.track_indices.len()
    }
}

